# Fenêtres d'approfondissement de la Phase A. Faits déjà sourcés dans evidence/.
from moteur import fen, table

S = lambda *n: "".join(f'<sup class="s">{i}</sup>' for i in n)

def P(*a):
    return "<p>" + "".join(a) + "</p>"

lecture_score = fen("w-score-lire", "Trois patients, le score calculé ligne à ligne", f"""
{P("Patient A. Femme de 28 ans, Basedow connu, a arrêté le carbimazole depuis cinq jours. Température 38,6 °C. Pouls 132, régulier. Agitation sans délire. Deux vomissements, pas d'ictère. Pas de râles. L'arrêt du médicament est un facteur précipitant.", S(5))}
{P("Température 38,6 °C tombe dans la classe 38,4 à 38,8 : 15 points. Fréquence 132 : classe 130 à 139, 20 points. Pas de fibrillation : 0. Insuffisance cardiaque absente : 0. Vomissements : atteinte digestive modérée, 10 points. Agitation : système nerveux léger, 10 points. Facteur précipitant présent : 10 points. Total 15 + 20 + 10 + 10 + 10 = 65. Le total dépasse 45 : crise, traitement agressif. On ne retire pas les vomissements sous prétexte qu'une gastrite pourrait les expliquer : le doute les garde dans le score.", S(5))}
{P("Patient B. Homme de 70 ans, goitre multinodulaire, lendemain d'un scanner injecté. Température 37,9 °C. Fibrillation à 124. Pas de confusion. Nausée une fois. Pas d'œdème pulmonaire. Le produit de contraste est un facteur précipitant.", S(1, 5))}
{P("Température 37,9 °C : classe 37,8 à 38,3, 10 points. Fréquence 124 : classe 120 à 129, 15 points. Fibrillation : 10 points. Cœur absent au sens de l'insuffisance : 0. Nausée : digestif modéré, 10 points. Système nerveux absent : 0. Précipitant : 10. Total 10 + 15 + 10 + 10 + 10 = 55. Encore au-dessus de 45. Le scanner n'est pas une contre-indication au thionamide : c'est le déclencheur. L'iode du contraste est déjà dans le patient. On donne quand même le thionamide tout de suite. On n'ajoute pas un deuxième apport d'iode nucléaire.", S(5, 12))}
{P("Patient C. Femme de 50 ans, thyrotoxicose modérée, angine. Température 37,4 °C. Pouls 96, régulier. Pas de vomissement, pas de confusion, pas d'insuffisance cardiaque. L'angine peut être le début d'une agranulocytose, pas forcément une crise.", S(8))}
{P("Température 37,4 °C : 5 points. Fréquence 96 : classe 90 à 109, 5 points. Le reste est à 0 si l'on ne compte pas l'angine comme précipitant thyrotoxique. Total 10. Sous 25 : crise peu probable. On arrête le carbimazole pour l'angine, on fait la formule sanguine, on ne démarre pas le protocole d'iode. Les deux urgences ne se traitent pas de la même façon.", S(5, 8))}
{P("Le critère japonais sur les mêmes patients. Patient A : thyrotoxicose connue, agitation (signe neurologique), fièvre au-dessus de 38 °C, fréquence au-dessus de 130, vomissements. TS1 par la première combinaison. Patient B : pas de signe neurologique, mais fièvre, fréquence au-dessus de 130, nausée, et le cœur est en fibrillation sans insuffisance décrite. Fièvre, tachycardie et atteinte digestive font trois signes : TS1 par la combinaison alternative. Patient C : fièvre sous 38 °C au sens du critère japonais (37,4), fréquence sous 130. Pas de TS1 ni de TS2. Les deux systèmes concordent ici. Quand ils divergent, le texte de 2016 demande de les utiliser ensemble et de juger le patient, pas de moyenner les points.", S(5))}
""")

nodules = fen("w-nodules-lire", "Quatre nodules, les points additionnés", f"""
{P("Nodule 1. Entièrement kystique, anéchogène, marge lisse, pas de foyer échogène, plus large que haut. Composition 0, échogénicité 0, marge 0, foyers 0, forme 0. Total 0 : TR1. Pas de cytoponction, pas de suivi échographique pour ce motif. Si la thyréostimuline est basse, ce kyste n'explique en général pas une hyperthyroïdie : on cherche un autre foyer chaud.", S(6))}
{P("Nodule 2. Spongiforme, isoéchogène, marge lisse, queues de comète larges, plus large que haut. Composition spongiforme 0. Le reste peut ajouter des points, mais un nodule seulement spongiforme sans signe suspect reste bas. S'il n'a aucun signe de suspicion, il ne va pas à la cytoponction quelle que soit sa taille. On ne lui applique pas le seuil de 2 cm d'une autre société : ce cours suit le texte de 2017.", S(6))}
{P("Nodule 3. Solide, isoéchogène, marge lisse, pas de calcification, plus large que haut. Solide 2, isoéchogène 1, marge 0, foyers 0, forme 0. Total 3 : TR3. Cytoponction si le plus grand diamètre atteint 2,5 cm. Suivi si 1,5 cm. À 1,2 cm, ni ponction ni suivi selon ce barème. On mesure le plus grand diamètre, on ne convertit pas en volume pour changer de classe.", S(6))}
{P("Nodule 4. Solide, très hypoéchogène, marge irrégulière, foyers ponctués, plus haut que large. Solide 2, très hypoéchogène 3, marge irrégulière 2, foyers ponctués 3, forme 3. Total 13 : TR5. Cytoponction dès 1,0 cm. Suivi dès 0,5 cm. En dessous de 0,5 cm, le texte de la catégorie TR5 ne demande pas de suivi systématique dans le tableau repris en 2018. Une extension hors de la thyroïde, si elle était là, ajouterait 3 à la place de la marge irrégulière, pas en plus : on ne choisit qu'une marge.", S(6))}
{P("Nodule mixte. Mixte 1, hypoéchogène 2, marge lisse 0, macrocalcification 1, plus large que haut 0. Total 4 : TR4. Cytoponction à partir de 1,5 cm, suivi à partir de 1,0 cm. La macrocalcification ne fait pas à elle seule un TR5. Les foyers ponctués, eux, pèsent 3 et font souvent basculer.", S(6))}
{P("Lien avec l'hormone. Un nodule TR5 chez un patient en thyrotoxicose peut être un cancer et un nodule chaud n'est pas toujours bénin au sens cytologique. La scintigraphie répond à la question de l'autonomie. L'échographie classée répond à la question du cancer. On ne remplace pas l'une par l'autre. Avant un iode radioactif pour un goitre nodulaire, la recommandation de 2016 demande d'avoir regardé les nodules.", S(2, 6))}
""")

suivi = fen("w-suivi", "Calendrier de contrôle, phrase par phrase", f"""
{P("Lévothyroxine orale, Euthyrox, numéro 54949. La dose d'entretien de l'hypothyroïdie est écrite de 100 à 200 µg par jour, après un début de 25 à 50 et des paliers toutes les 2 à 4 semaines. Chez la personne âgée, l'hypothyroïdie ancienne ou le patient cardiaque, le début lu est de 25 µg. On ne saute pas à la dose d'entretien le premier jour dans ces cas.", S(9))}
{P("La revue lausannoise de 2010 propose, avant 60 ans et sans ischémie, une demi-dose puis la dose complète quatre à six semaines plus tard, et au-delà de 60 ans ou avec ischémie une montée très progressive. L'information professionnelle d'Euthyrox, elle, écrit un début à 25 µg chez la personne âgée, l'hypothyroïdie ancienne ou le patient cardiaque. On retient ce début de 25 µg. On ne fabrique pas un palier plus petit que le comprimé lu.", S(1, 9))}
{P("Contrôle. Trois mois après l'introduction, quatre à six semaines après chaque changement, puis une fois par an. On évite une thyréostimuline sous 0,4 mU/l à cause du risque osseux et de fibrillation discuté dans la revue. Après un changement, on n'interprète pas un dosage fait à trois jours : l'équilibre n'est pas là.", S(1))}
{P("Carbimazole. Durée habituelle écrite dans l'information professionnelle : 6 à 18 mois. Durée citée pour Basedow dans la revue : douze à dix-huit mois. Durée citée par la recommandation de 2016 si l'on choisit le thionamide : environ 12 à 18 mois, arrêt si la thyréostimuline et l'anticorps anti-récepteur sont normaux. On dit au patient les trois formulations. On ne présente pas une durée unique inventée.", S(1, 2, 8))}
{P("Formule sanguine. Surtout les deux premiers mois, et au-dessus de 40 mg par jour, avant le traitement puis chaque semaine pendant six semaines si le patient a plus de 40 ans. Tout patient, quel que soit l'âge, arrête et consulte devant fièvre, aphtes ou angine, sans attendre la date du contrôle.", S(8))}
{P("Amiodarone. Avant de commencer, un bilan thyroïdien. Ensuite, le profil euthyroïdien est attendu. La recommandation européenne surveille l'hypothyroïdie induite tous les 4 à 6 mois quand on a choisi de ne pas traiter une forme infraclinique. Ce délai n'est pas un délai d'urgence : une thyrotoxicose clinique se dose le jour même.", S(4))}
{P("Après une crise ou un coma, le contrôle est clinique d'heure en heure, pas trimestriel. La thyréostimuline du coma ne sert pas de cible quotidienne. On juge la conscience, la température, la ventilation et le cœur.", S(3))}
""")

cas_crise = fen("w-cas-crise", "Cas de crise, correction complète", f"""
{P("Énoncé. Homme de 61 ans, goitre connu, amené pour agitation et diarrhée. Température 39,6 °C. Fréquence 148, irrégulière. Crépitants aux deux bases. Ictère conjonctival. Il a reçu un produit de contraste il y a 48 heures pour une embolie pulmonaire suspectée, finalement écartée. Thyroxine libre 72 pmol/l, thyréostimuline indétectable, triiodothyronine libre haute. Que faites-vous dans l'heure, et dans quel ordre ?")}
{P("Correction, score. Température 39,6 °C : classe 39,4 à 39,9, 25 points. Fréquence 148 : 25 points. Fibrillation : 10. Insuffisance cardiaque au moins modérée, bases crépitantes : 10, et l'on peut discuter sévère à 15 si le tableau hémodynamique est mauvais. On retient 10 tant que le choc n'est pas décrit, et on le dit. Ictère : digestif sévère, 20. Agitation : système nerveux léger, 10, sauf si le délire est net, alors 20. Précipitant, le contraste : 10. Total prudent 25 + 25 + 10 + 10 + 20 + 10 + 10 = 110. Très au-dessus de 45. Critère japonais : fièvre, tachycardie au-dessus de 130, insuffisance cardiaque, ictère, agitation. TS1.", S(5))}
{P("Ordre des médicaments. Voie veineuse, scope, soins intensifs. Propranolol 10-40 mg par la bouche, 3 à 4 fois par jour, si la pression le permet, numéro 47025. Si le patient vomit, on ne invente pas une forme intraveineuse qui n'est pas dans cette information professionnelle de comprimés : on demande la forme disponible sur place et on s'en tient à une information professionnelle lue. Carbimazole 20 à 60 mg par jour, en visant le haut de la fourchette vu l'ampleur, sans dépasser 60 mg par jour, numéro 21037, par sonde si besoin. Au moins une heure après, iode minéral. Pas le comprimé 67017 de 130.0 mg, contre-indiqué dans l'hyperthyroïdie. Hydrocortisone : 100 mg intraveineux puis 100 mg toutes les 6 heures, numéro 23533, comme dose de stress déjà écrite. Refroidissement, remplissage prudent vu les crépitants, traitement de toute infection.", S(5, 8, 10, 11, 12))}
{P("Ce que l'on ne fait pas. On ne donne pas d'iode radioactif aujourd'hui. On ne fait pas de scanner injecté supplémentaire. On n'attend pas l'anticorps anti-récepteur pour la première dose de carbimazole. On n'attribue pas la diarrhée et l'ictère à une gastro-entérite qui dispenserait du score. On prévient l'équipe que l'agranulocytose reste un risque du thionamide même en crise.", S(8))}
""")

cas_coma = fen("w-cas-coma", "Cas de coma myxœdémateux, correction", f"""
{P("Énoncé. Femme de 74 ans, hypothyréodienne connue, retrouvée confuse et froide. Température 34,8 °C. Fréquence 46. Fréquence respiratoire 8. Natrémie 122 mmol/l. Glycémie 3,2 mmol/l. Visage bouffi, réflexes lents. La fille dit qu'elle ne prenait plus la lévothyroxine depuis trois semaines. Thyroxine libre basse sur un dosage ancien. Que faites-vous avant le retour du laboratoire d'aujourd'hui ?")}
{P("Correction. Le tableau est celui décrit en 2014 : hypothermie, hypoventilation, hyponatrémie, hypoglycémie, trouble de conscience, contexte d'hypothyroïdie décompensée. On n'attend pas la thyréostimuline du jour. Son niveau ne gradue pas la gravité. On hospitalise en soins intensifs. On ventile si la fréquence respiratoire et la gazométrie l'exigent. On corrige le glucose. On remonte le sodium sans correction brutale, selon les règles de l'hyponatrémie qui ne sont pas re-détaillées ici. On réchauffe sans provoquer une vasodilatation agressive.", S(3))}
{P("Ordre hormonal. Cortisol si le tube part tout de suite, puis hydrocortisone 100 mg intraveineux, numéro 23533, avant la lévothyroxine. La recommandation de 2014 est explicite : le glucocorticoïde précède l'hormone thyroïdienne. Ensuite lévothyroxine intraveineuse, charge de 200 à 400 microgrammes, dose basse de cette fourchette chez cette patiente âgée. Puis la dose quotidienne de 1,6 microgramme par kilogramme réduite du quart tant que la voie reste intraveineuse. Cette forme intraveineuse n'est pas dans l'index suisse lu. On le dit, on ne substitue pas les comprimés d'Euthyrox dans la tubulure.", S(3, 9, 11))}
{P("On cherche le facteur déclenchant : infection, infarctus, médicament sédatif, froid. On ne donne pas de liothyronine d'emblée à forte dose. Si on l'ajoute, la fourchette lue est une charge de 5 à 20 microgrammes puis 2,5 à 10 microgrammes toutes les 8 heures, plus bas chez la personne âgée ou coronarienne, parce que des triiodothyronines hautes sous traitement ont été associées à la mortalité.", S(3))}
{P("Cible. Conscience, ventilation, cœur, température. Pas une thyréostimuline normale à la douzième heure. Les hormones peuvent être re-dosées tous les un à deux jours pour voir la trajectoire, pas pour courir après un chiffre.", S(3))}
""")

cas_amio = fen("w-cas-amio", "Deux patients sous amiodarone", f"""
{P("Patient 1. Homme de 68 ans, Cordarone 200 mg par jour, numéro 33393, depuis six semaines pour une fibrillation. Thyroxine libre un peu haute, triiodothyronine basse, thyréostimuline à 6 mU/l, pas d'amaigrissement, poids stable. C'est le profil court terme lu en 2018 : effet de Wolff-Chaikoff et inhibition de la désiodase. On n'arrête pas l'amiodarone. On ne donne pas de carbimazole. On prévient le cardiologue et on recontrôle.", S(4, 14))}
{P("Patient 2. Femme de 71 ans, amiodarone depuis deux ans, amaigrissement, pouls à 120, thyroxine libre très haute, triiodothyronine libre haute, thyréostimuline effondrée. Thyroïde nodulaire connue. Doppler : vascularisation augmentée. Anticorps anti-récepteur négatifs. En Suisse, l'apport d'iode est suffisant pour que la scintigraphie soit basse dans les deux types : on ne l'utilise pas pour trancher. Le terrain nodulaire et le Doppler riche orientent vers un type 1. On traite par carbimazole, dans la fourchette 20 à 60 mg par jour, numéro 21037. On n'ajoute pas d'emblée la prednisone si rien ne suggère une destruction. On réévalue à quatre à six semaines. Si rien ne bouge, on discute l'ajout du glucocorticoïde pour une forme mixte. L'arrêt de l'amiodarone se décide avec le cardiologue, pas seul.", S(4, 8))}
{P("Patient 3, pour le type 2. Homme sans goitre, amiodarone depuis trente mois, thyrotoxicose, Doppler sans hypervascularisation, anticorps absents. La recommandation retient le glucocorticoïde en première ligne. L'essai cité utilisait 30 mg par jour de prednisone. Prednisone Streuli, numéro 29349, écrit 15 à 30 mg par jour pour une maladie aiguë qui ne met pas le pronostic vital en jeu. On situe la dose de l'essai dans cette fourchette, et on dit que l'information professionnelle ne nomme pas la thyrotoxicose à l'amiodarone. Si le cœur se dégrade, la thyroïdectomie ne se discute pas au bout de semaines : la recommandation la veut sans délai.", S(4, 13))}
{P("Hypothyroïdie sous le même médicament. Thyréostimuline à 28 mU/l, thyroxine libre basse : forme franche, lévothyroxine, amiodarone maintenue si elle est indispensable. Thyréostimuline à 8 mU/l, thyroxine libre normale, patient de 80 ans : on peut surveiller tous les 4 à 6 mois sans traiter, selon la recommandation, en expliquant le risque de passage à la forme franche.", S(4, 9))}
""")

cas_faux = fen("w-cas-faux", "Biotine, basse T3, et le piège surrénalien", f"""
{P("Biotine. Étudiant de 22 ans, bilan demandé pour fatigue. Thyréostimuline indétectable, thyroxine libre 110 pmol/l, triiodothyronine libre haute. Pouls 64. Poids stable. Pas de tremblement. Pas de goitre. Il prend un comprimé « cheveux et ongles » à forte dose depuis un mois. On n'envoie pas au bloc et on ne commence pas le carbimazole. On arrête le comprimé. On reprend le dosage après au moins 2 jours, et le texte australien dit 72 heures. Si le second dosage est normal et que la clinique n'a jamais collé, c'était l'interférence. Si la clinique apparaît entre-temps, on reprend la démarche de la thyrotoxicose vraie.", S(2, 7))}
{P("Basse T3. Homme de 58 ans, jour 2 d'une pneumonie en soins intensifs, sans antécédent thyroïdien. Triiodothyronine très basse, thyréostimuline basse, thyroxine libre encore normale. On ne commence pas Euthyrox. On traite la pneumonie. On répète le bilan à distance, pas pour « corriger » la triiodothyronine. La recommandation de 2014 est contre la lévothyroxine et contre la liothyronine dans ce syndrome.", S(3))}
{P("Le même homme, s'il était déjà sous lévothyroxine pour une thyroïdectomie, garderait son traitement. On ne l'arrête pas parce que la triiodothyronine de la réanimation est basse.", S(3))}
{P("Surrénale. Femme de 40 ans, thyréostimuline à 48 mU/l, thyroxine libre basse, anticorps anti-thyroperoxydase positifs, fatigue, hypotension, natrémie basse. Avant la première lévothyroxine, on pense à l'insuffisance surrénale associée. La revue de 2010 le marque comme implication pratique : l'hormone thyroïdienne peut précipiter la crise. On dose le cortisol, on couvre si le doute est réel, puis seulement on substitue la thyroïde. Euthyrox se commence bas si le cœur est fragile, à 25 µg dans la phrase lue pour le sujet âgé ou cardiaque. Ici la patiente a 40 ans : le début de 25 à 50 du tableau d'hypothyroïdie s'applique, après la question surrénalienne.", S(1, 9))}
""")

interactions = fen("w-inter", "Absorption, métabolisme, et ce qui fausse le contrôle", f"""
{P("Euthyrox se prend le matin, et la spécialité voisine Eltroxine se prend 30 minutes avant le petit-déjeuner, en une fois. Un contrôle fait chez un patient qui prend le comprimé avec le café et le calcium du petit-déjeuner montre une thyréostimuline haute qui n'est pas un échec de la dose théorique.", S(9, 15))}
{P("La revue de 2010 liste ce qui diminue l'absorption : sels de calcium, fer, hydroxyde d'aluminium, cholestyramine. Ce qui accélère le métabolisme : phénytoïne, carbamazépine, phénobarbital, rifampicine. On espace le calcium et le fer de la lévothyroxine. On ne double pas la dose de mémoire quand on ajoute de la rifampicine : on recontrôle et on adapte.", S(1))}
{P("Grossesse et œstrogènes augmentent les besoins. La revue demande un contrôle plus fréquent, et un avis spécialisé pour toute atteinte pendant la grossesse. Sans borne locale, limite haute d'environ 4,0 mU/l pour l'ATA de 2017, et 2,5 mU/l, 3,0 mU/l, 3,5 mU/l selon le trimestre pour l'ETA de 2014.", S(1))}
{P("Sous carbimazole, un surdosage prolongé fait monter la thyréostimuline et grossir le goitre. Ce n'est pas une aggravation de Basedow : c'est un excès de thionamide. On baisse vers 5 à 20 mg par jour quand l'euthyroïdie est obtenue.", S(8))}
{P("Le propranolol de l'hyperthyroïdie masque la tachycardie. Une fréquence à 80 sous bêtabloquant ne prouve pas l'euthyroïdie. On se fie à la thyroxine libre et à la clinique, pas au pouls seul.", S(10))}
""")

populations = fen("w-pop", "Enfant, personne âgée, foie, contre-indications", f"""
{P("Carbimazole chez l'adolescent dès 12 ans. L'information professionnelle, numéro 21037, écrit une dose initiale de 0,7 à 0,8 mg par kilogramme et par jour, en deux ou trois prises, sans dépasser 60 mg par jour. L'entretien se réduit comme chez l'adulte. On ne recopie pas une dose forfaitaire d'adulte : on calcule au poids, et on reste sous le plafond de 60 mg par jour.", S(8))}
{P("Avant 12 ans, les données sont dites extrêmement limitées, sans étude systématique, surtout chez le nourrisson. Le traitement est instauré et surveillé par un médecin qui a l'expérience de cet âge. La dose initiale lue est la même, 0,7 à 0,8 mg par kilogramme, mais le plafond est de 30 mg par jour, pas 60. Avant 3 ans, la phrase est encore plus nette : spécialiste, et seulement après un rapport bénéfices-risques minutieux.", S(8))}
{P("Chez la personne âgée, le même texte dit qu'aucune adaptation chiffrée n'est requise pour le carbimazole, tout en renvoyant aux précautions. Ce n'est pas une permission d'ignorer le cœur : le propranolol et la dose haute se discutent avec le terrain.", S(8))}
{P("Foie et rein. Peu de données de pharmacocinétique. Insuffisance hépatique légère ou modérée : prudence, demi-vie allongée. Insuffisance hépatique sévère : contre-indication. Insuffisance rénale : prudence et contrôles thyroïdiens réguliers. On ne donne pas le chiffre d'une adaptation que le texte ne donne pas.", S(8))}
{P("Autres contre-indications lues du carbimazole : hypersensibilité, cancer de la thyroïde dépendant de la thyréostimuline, compression trachéale, goitre simple sans hyperthyroïdie, affection hématologique sévère et en particulier granulopénie, antécédent de pancréatite aiguë après carbimazole ou thiamazole. Un goitre simple n'est pas une indication. Une angine avec neutropénie déjà là est une contre-indication, pas un motif pour augmenter la dose.", S(8))}
{P("Lévothyroxine chez l'enfant, Euthyrox, numéro 54949. Dès 12 ans, la posologie adulte. Avant 12 ans, la dose par kilogramme est plus haute et se règle au cas par cas. Le tableau lu dit : de 0 à 6 mois, 25 à 75 µg, soit 10 µg par kilogramme ; de 6 à 12 mois, 50 à 75 µg, soit 8 µg par kilogramme ; de 1 à 5 ans, 75 à 100 µg, soit 5 à 6 µg par kilogramme ; de 6 à 12 ans, 100 à 150 µg, soit 4 à 5 µg par kilogramme. Les paliers se font toutes les 2 à 4 semaines. Avant un an, la dose du jour se donne au moins une demi-heure avant le premier repas, comprimé délayé dans un peu d'eau, suspension préparée juste avant.", S(9))}
{P("Les contre-indications lues d'Euthyrox incluent l'insuffisance cardiaque avec tachycardie, la pancardite aiguë, la myocardite aiguë, l'infarctus aigu, l'angine de poitrine, et les troubles hypophysaires ou surrénaliens non traités. Le début à 25 µg chez le sujet âgé ou cardiaque n'efface pas ces contre-indications : il décrit comment commencer quand le traitement est malgré tout indiqué et que l'épisode aigu est passé. Une insuffisance surrénale non traitée reste une contre-indication, ce qui rejoint l'ordre du coma : glucocorticoïde d'abord.", S(9, 3))}
{P("Allaitement. Si la femme allaite sous carbimazole, la dose ne dépasse pas 20 mg par jour, répartie, prise juste après la tétée, et elle est informée du risque pour l'enfant. On ne promet pas une innocuité que le texte ne promet pas.", S(8))}
{P("Récidive après un arrêt de carbimazole. Le texte dit que l'on peut reprendre le médicament, mais qu'il faut envisager un autre traitement, en particulier la chirurgie. Ce n'est pas un échec moral du patient. C'est la phrase de l'information professionnelle.", S(8))}
""")

cas_deq = fen("w-cas-deq", "Thyroïdite, nodule chaud, hypothyroïdie centrale", f"""
{P("Thyroïdite. Femme de 42 ans, douleur cervicale irradiant vers l'oreille depuis quatre jours, fièvre à 38,1 °C, pouls à 110, thyroïde très sensible. Thyroxine libre haute, thyréostimuline basse, vitesse de sédimentation haute dans l'esprit du tableau que la revue associe à De Quervain. Pas de confusion, pas de vomissement, pas d'ictère. Score : température 38,1 °C vaut 10 points, fréquence 110 à 119 vaut 10, le reste est pauvre. Total autour de 20 si l'on ne compte pas la douleur comme précipitant. Sous 25 : pas une crise. Le mécanisme est une fuite de stock, pas une fabrication. Le carbimazole ne sert pas et expose à l'agranulocytose. La revue retient les anti-inflammatoires et la prednisone pour l'inflammation de De Quervain. Prednisone Streuli, numéro 29349, écrit 15 à 30 mg par jour pour une maladie aiguë qui ne met pas le pronostic vital en jeu. On situe la prednisone dans cette fourchette, pour quelques jours, puis on baisse. On prévient : après la phase haute vient souvent une phase basse, transitoire. On ne commence pas une lévothyroxine à vie au premier dosage bas de la troisième semaine.", S(1, 5, 13))}
{P("Nodule chaud. Homme de 66 ans, thyréostimuline basse, thyroxine libre normale, triiodothyronine libre haute, nodule unique à droite. Scintigraphie : foyer droit, reste de la glande éteint. C'est un nodule autonome, pas un Basedow. L'anticorps anti-récepteur, s'il est négatif, va dans le même sens. L'échographie classe le nodule à part, pour le cancer. Un nodule solide isoéchogène à marge lisse de 2,8 cm est un TR3 : la cytoponction se discute à partir de 2,5 cm. Le traitement de l'autonomie, chirurgie ou iode radioactif, se décide avec l'endocrinologue. Le carbimazole peut préparer, il ne guérit pas l'autonomie. Le bêtabloquant traite le cœur en attendant.", S(2, 6, 8, 10))}
{P("Hypothyroïdie centrale. Femme de 36 ans, fatigue, aménorrhée, thyroxine libre basse, thyréostimuline à 0,8 mU/l dans des bornes basses. On ne dit pas que la thyroïde va bien parce que la thyréostimuline n'est pas haute. On cherche l'hypophyse : autres déficits, imagerie. On ne donne pas la lévothyroxine avant d'avoir écarté ou couvert le déficit corticotrope. Euthyrox est contre-indiqué si la surrénale n'est pas traitée. La cible ensuite n'est pas une thyréostimuline normale, qui ne montera pas : c'est la thyroxine libre.", S(1, 9))}
{P("Prise cachée. Infirmière, thyroxine libre très haute, triiodothyronine moins haute, thyréostimuline effondrée, thyroïde petite, fixation nulle, pas de douleur. Le rapport penche vers une prise exogène, comme la recommandation de 2016 le décrit pour la thyrotoxicose factice. On ne donne pas de carbimazole. On cherche la prise, on arrête l'apport, on surveille le cœur. La scintigraphie basse ressemble à une thyroïdite : la clinique, l'absence de douleur et le rapport des hormones séparent les deux.", S(2))}
{P("Grossesse, ce que l'on dit et ce que l'on ne dit pas. Toute atteinte thyroïdienne chez une femme enceinte mène à un avis spécialisé. Le dépistage systématique de toutes les adultes n'est pas recommandé. Il l'est en début de grossesse si le risque est augmenté. On cite les deux jeux de seuils lus, ATA 2017 et ETA 2014, et l'on ne les moyenne pas. Le carbimazole passe le placenta : une dose inadaptée peut donner un goitre fœtal, une hypothyroïdie et un petit poids de naissance. On ne promet pas un schéma unique.", S(1, 8))}
""")

consultation = fen("w-consult", "Déroulement d'une consultation, de la porte à l'ordonnance", f"""
{P("La consultation commence par la stabilité, pas par le commentaire du laboratoire. On demande si le patient tient debout, s'il a de la fièvre, s'il est confus, s'il a vomi, s'il a une douleur thoracique. Une réponse oui sur la fièvre avec agitation, ou sur le coma avec froid, sort du bureau : c'est l'hôpital. Le reste peut s'asseoir.")}
{P("On fait dire la liste des médicaments, y compris ceux qui ne sont pas sur l'ordonnance : amiodarone, lithium, corticoïde, complément pour les cheveux, lévothyroxine d'un autre médecin, produit de contraste des dernières semaines. On demande la grossesse et l'allaitement avant toute scintigraphie et avant de choisir la dose de carbimazole.", S(8, 12))}
{P("On regarde le profil dans l'ordre. Thyréostimuline seule : on ne conclut pas. Thyroxine libre ensuite. Triiodothyronine libre si la thyréostimuline est basse et la thyroxine libre encore dans les bornes du laboratoire, ou si le patient est en réanimation. On note les bornes du laboratoire sur le compte rendu, pas celles d'un autre hôpital. Les bornes du Centre hospitalier universitaire vaudois publiées en 2010, thyroxine libre 8 à 22 pmol/l et thyréostimuline 0,2 à 3,5 mU/l, illustrent cette variabilité. Une limite haute de thyréostimuline à 4,5 mU/l dans la littérature n'annule pas le compte rendu local.", S(1))}
{P("On examine le cou et les yeux avant de cocher un diagnostic sur le logiciel. Goitre diffus soufflant et orbitopathie : maladie de Basedow, anticorps anti-récepteur utile, scintigraphie souvent inutile. Nodule : échographie classée de TR1 à TR5, et scintigraphie si la thyréostimuline est basse. Cou douloureux : thyroïdite, pas de thionamide. Thyroïde petite et hormones très hautes sans douleur : prise exogène ou thyroïdite silencieuse.", S(2, 6))}
{P("L'ordonnance, quand elle est indiquée, nomme la spécialité et le numéro. Carbimazole : Néo-Mercazole, 21037, 20 à 60 mg par jour au début, puis descente vers 5 à 20 mg, plafond 60 mg, et 30 mg avant 12 ans. Le patient repart avec la phrase sur la fièvre et l'angine. Propranolol : 47025, 10-40 mg trois à quatre fois par jour pour l'hyperthyroïdie, pas la dose de l'hypertension. Lévothyroxine : Euthyrox, 54949, début bas à 25 µg si le patient est âgé ou cardiaque, entretien dans la zone 100 à 200 µg, à jeun. On écrit l'heure de la prise et on écarte le calcium et le fer.", S(8, 9, 10))}
{P("On fixe la date du prochain dosage avant que le patient parte. Sous lévothyroxine, pas avant quatre à six semaines après un changement. Sous carbimazole, clinique rapprochée et formule selon l'âge et la dose. Sous amiodarone sans symptôme, le profil euthyroïdien se recontrôle, pas un thionamide préventif. Enceinte : rendez-vous spécialisé, pas un seuil récité de mémoire.", S(1, 4, 8))}
{P("La lettre au confrère dit trois choses : le profil chiffré avec les bornes, le mécanisme retenu, et ce qui a été exclu. Elle ne dit pas hyperthyroïdie sans dire fabrication, fuite ou prise. Elle ne dit pas hypothyroïdie sans dire primaire ou centrale. Elle mentionne la biotine si le chiffre et la clinique se contredisent.", S(7))}
{P("À l'examen fédéral, la réponse gagne des points si elle donne l'ordre. D'abord la défaillance. Ensuite le mécanisme. Ensuite le médicament suisse avec sa limite. Ensuite le piège : iode avant thionamide, comprimé nucléaire dans la crise, hormone thyroïdienne avant le glucocorticoïde du coma, thionamide dans une thyroïdite, traitement d'une basse T3 de réanimation, score appliqué à un patient euthyroïdien. Une réponse qui nomme Basedow devant toute thyréostimuline basse est fausse, même si Basedow est fréquent chez la femme jeune.", S(2, 3, 5))}
{P("Ce que l'on écrit dans le dossier le jour même. Le profil avec les unités, mU/l ou pmol/l selon le laboratoire. Le pouls, la température, le poids et son évolution. La présence ou l'absence d'orbitopathie, de douleur cervicale, de nodule. Les médicaments, y compris la biotine. La décision : urgence, traitement ambulatoire, ou simple contrôle. Le nom du médicament, la dose du jour, la dose plafond, et la consigne d'arrêt. La date du prochain dosage. Si un chiffre n'a pas été lu dans une source, il n'entre pas dans cette note.")}
{P("Ce que l'on n'écrit pas. Une prévalence suisse des dix diagnostics, qu'aucun texte lu ne donne. Une autorisation suisse de lévothyroxine intraveineuse. Les seuils de grossesse, le score de Popoveniuc et la dose de propylthiouracile de la crise sont, eux, écrits depuis les textes de 2017, 2014 et 2016. Une indication du comprimé d'iodure nucléaire dans la crise. Ces absences sont assumées. Elles ne trouent pas les classifications qui, elles, ont été lues en entier : score de Burch-Wartofsky, critères japonais TS1 et TS2, catégories TR1 à TR5, types 1 et 2 de la thyrotoxicose à l'amiodarone, et les huit profils hormonaux.", S(4, 5, 6))}
{P("Passage de relais. Le médecin de premier recours garde l'hypothyroïdie primaire stable et une part des formes infracliniques, avec un spécialiste facilement joignable. Il adresse l'hyperthyroïdie, la grossesse, l'enfant surtout avant trois ans, l'amiodarone, le nodule qui atteint un seuil de cytoponction, et toute défaillance. La revue de 2010 le dit : hors les formes sévères et la grossesse, beaucoup de dysthyroïdies se suivent au cabinet, mais les choix de l'hyperthyroïdie se discutent avec l'endocrinologue.", S(1, 6, 8))}
{P("Dernière vérification avant d'imprimer l'ordonnance. Le patient a-t-il compris qu'il arrête le carbimazole s'il a de la fièvre. A-t-il compris qu'il prend la lévothyroxine à jeun. A-t-il une carte ou un proche prévenu s'il est à risque de crise. La femme en âge de procréer a-t-elle un test ou un avis. Le patient sous amiodarone sait-il que sa thyroxine libre peut être haute sans qu'il soit malade. Ces quatre phrases évitent plus d'erreurs qu'un dosage supplémentaire.", S(4, 8, 9))}
{P("Contrôle de cohérence avant de fermer le dossier. La dose de carbimazole du jour est-elle au plus égale à 60 mg chez l'adulte et à 30 mg avant 12 ans. La dose de propranolol est-elle celle de l'hyperthyroïdie, 10-40 mg trois à quatre fois, et non celle de l'hypertension. L'hydrocortisone de stress est-elle de 100 mg, pas un schéma inventé. L'iode nucléaire de 130.0 mg est-il resté dans sa contre-indication. La lévothyroxine orale commence-t-elle à 25 µg quand le cœur ou l'âge l'exigent. Si une de ces phrases ne tient pas, l'ordonnance ne part pas.", S(8, 9, 10, 11, 12))}
{P("Le texte de la leçon date du 31 octobre 2026. Il suit les informations professionnelles du corpus local et les recommandations lues cette session. Il ne remplace pas l'ordonnance du moment ni le compte rendu du laboratoire qui a rendu le chiffre. Un résultat discordant avec la clinique s'arrête, se rediscute, et ne se traite pas pour faire taire un nombre. On relit aussi l'unité : mU/l n'est pas pmol/l, et une thyroxine libre à 48 pmol/l n'est pas une thyréostimuline à 48 mU/l. Confondre les deux inverse le diagnostic. On écrit aussi le numéro Swissmedic à côté de la dose, pour que la phrase puisse être relue dans l'information professionnelle et pas dans un aide-mémoire non daté.")}
""")

